self.KB_CONTENT["card:756456"]={"id":"card:756456","ty":"card","sourceId":"756456","title":"『客戶資料變更建立作業』的作業重點有哪些？","ver":"iGP","topic":"客戶","keywords":["客戶","控管"],"y":"explain","answer":"1.以客戶代號+變更版次做控管，以最後變更的資料確認後寫回客戶資料內。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
